#!/usr/bin/env python3
"""Tolerance for the weighted second variation of the jump-subtracted L=.75 residual."""
import json,math
from pathlib import Path
root=Path(__file__).parents[1]/'results';tail=json.loads((root/'L075_infinite_residual_tail_tolerance.json').read_text());jump=json.loads((root/'L075_directed_jump_tail.json').read_text());block=json.loads((root/'L075_continuous_remainder_first_tail_block.json').read_text());allow=tail['maximum_orthogonal_tail_norm'];j=3.3641612348666706e-9;cont_allow=math.sqrt(max(0,allow*allow-j*j));L=.75;N=1000;factor=4*math.sqrt(L/(3*math.pi))/(N-1)**1.5;Vmax=cont_allow/factor;# infer diagnostic V from first block under n^-2 model: block^2 = C^2 sum n^-4, C=4sqrt(L/pi)V
b=1.9791894888102112e-10;s=sum(n**-4 for n in range(1000,1100,2));# only even coefficients: use exact sampled parity sum
C=b/math.sqrt(s);Vscout=C/(4*math.sqrt(L/math.pi));out={'schema':'marici.voevodsky.L075-second-variation-tolerance.v1','total_tail_allowance':allow,'directed_jump_tail_bound':j,'remaining_continuous_tail_allowance':cont_allow,'second_variation_tail_factor':factor,'maximum_weighted_second_variation':Vmax,'first_block_implied_second_variation_scout':Vscout,'scout_to_maximum_ratio':Vscout/Vmax,'passed_scout':Vscout<Vmax,'passed':False,'next_required':'directed assembly of weighted second variation from polynomial second derivatives, derivative jumps, and smooth gamma/endpoint rows','rh_proved':False};p=root/'L075_second_variation_tolerance.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));assert out['passed_scout']
